public class LengthGrouperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        java.util.Map<Integer, java.util.List<String>> m =
                LengthGrouper.byLength(java.util.List.of("cat", "dog", "horse", "ox", "zebra", "ant"));
        check("number of distinct lengths", 3, m.size());
        check("words of length 3 in encounter order", "[cat, dog, ant]", String.valueOf(m.get(3)));
        check("words of length 5 in encounter order", "[horse, zebra]", String.valueOf(m.get(5)));
        check("words of length 2", "[ox]", String.valueOf(m.get(2)));
        check("absent length maps to null", "null", String.valueOf(m.get(9)));
        java.util.Map<Integer, java.util.List<String>> single =
                LengthGrouper.byLength(java.util.List.of("hi"));
        check("single word grouped", "[hi]", String.valueOf(single.get(2)));
        java.util.Map<Integer, java.util.List<String>> none =
                LengthGrouper.byLength(new java.util.ArrayList<String>());
        check("empty input gives empty map", 0, none.size());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

